print("Input -> Output:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{outp}'")

# Let me analyze character by character
print("\nCharacter-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n'{inp}' -> '{outp}':")
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(outp):
            print(f"  Position {j}: (added) '{outp[j]}'")

